    if (this.#isDesktop && this.#isCollapsed(target)) {
      this.#collapseAllExcept(target)
      this.#expand({ column: target })
    }
  }

  frameColumnOnMobile(event) {
    if (!this.#isDesktop) {
      event.currentTarget.scrollIntoView({ behavior: "smooth", inline: "center" })
    }
